{"security_risk":"MEDIUM","summary":"Create D3 visualization logic for bubble chart, legend, and linked table","command":"create","path":"/root/output/js/visualization.js","file_text":"/* global d3 */

(() => {
  const DATA_URL = 'data/stock-descriptions.csv';

  const chartEl = document.getElementById('chart');
  const legendEl = document.getElementById('legend');
  const tableEl = document.getElementById('stock-table');
  const tbodyEl = tableEl.querySelector('tbody');
  const tooltipEl = document.getElementById('tooltip');

  const state = {
    selectedTicker: null,
    byTicker: new Map(),
    rowByTicker: new Map(),
    nodeByTicker: new Map()
  };

  function parseNumber(v) {
    if (v == null) return null;
    const s = String(v).trim();
    if (!s || ['na', 'n/a', 'null', 'none'].includes(s.toLowerCase())) return null;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  }

  function fmtMarketCap(v) {
    if (v == null) return '—';
    // 1.64T style
    const s = d3.format('.3s')(v);
    return s.replace('G', 'B');
  }

  function isETF(d) {
    // In this dataset ETFs are sector=ETF and missing marketCap.
    return (d.sector || '').trim() === 'ETF' || d.marketCap == null;
  }

  function setSelectedTicker(ticker) {
    state.selectedTicker = ticker;

    for (const [t, tr] of state.rowByTicker.entries()) {
      tr.classList.toggle('selected', t === ticker);
    }

    for (const [t, g] of state.nodeByTicker.entries()) {
      g.classList.toggle('selected', t === ticker);
    }

    const row = state.rowByTicker.get(ticker);
    if (row) row.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }

  function showTooltip(event, d) {
    if (isETF(d)) return;

    tooltipEl.classList.add('visible');
    tooltipEl.innerHTML = [
      `<div style="font-weight:700; margin-bottom:4px;">${d.ticker}</div>`,
      `<div>${d.fullName || '—'}</div>`,
      `<div style="color: rgba(255,255,255,0.78); margin-top:4px;">Sector: ${d.sector || '—'}</div>`
    ].join('');

    moveTooltip(event);
  }

  function moveTooltip(event) {
    const pad = 12;
    const box = tooltipEl.getBoundingClientRect();
    let x = event.pageX + 12;
    let y = event.pageY - 10;

    const maxX = window.scrollX + document.documentElement.clientWidth - box.width - pad;
    const maxY = window.scrollY + document.documentElement.clientHeight - box.height - pad;

    x = Math.min(x, maxX);
    y = Math.min(y, maxY);

    tooltipEl.style.left = `${x}px`;
    tooltipEl.style.top = `${y}px`;
  }

  function hideTooltip() {
    tooltipEl.classList.remove('visible');
  }

  function makeColorScale(sectors) {
    const palette = [
      ...(d3.schemeTableau10 || []),
      ...(d3.schemeSet3 || []),
      ...(d3.schemePaired || [])
    ];

    return d3.scaleOrdinal()
      .domain(sectors)
      .range(sectors.map((_, i) => palette[i % palette.length]));
  }

  function computeSectorCenters(sectors, width, height) {
    const cols = Math.min(3, sectors.length);
    const rows = Math.ceil(sectors.length / cols);

    const xScale = d3.scalePoint()
      .domain(d3.range(cols))
      .range([width * 0.30, width * 0.70]);

    const yScale = d3.scalePoint()
      .domain(d3.range(rows))
      .range([height * 0.35, height * 0.65]);

    const centers = new Map();
    sectors.forEach((s, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      centers.set(s, { x: xScale(col), y: yScale(row) });
    });

    return centers;
  }

  function deterministicInit(nodes, centers) {
    // Deterministic starting positions: golden-angle spiral around the sector center.
    const golden = Math.PI * (3 - Math.sqrt(5));

    const bySector = d3.groups(nodes, d => d.sector)
      .sort((a, b) => d3.ascending(a[0], b[0]));

    for (const [, sectorNodes] of bySector) {
      sectorNodes.sort((a, b) => d3.ascending(a.ticker, b.ticker));
      const c = centers.get(sectorNodes[0].sector);

      sectorNodes.forEach((n, i) => {
        const a = i * golden;
        const r = 6 + 3.2 * Math.sqrt(i);
        n.x = c.x + r * Math.cos(a);
        n.y = c.y + r * Math.sin(a);
      });
    }
  }

  function renderLegend(sectors, color) {
    legendEl.innerHTML = '';

    sectors.forEach((s) => {
      const item = document.createElement('div');
      item.className = 'legend-item';

      const swatch = document.createElement('span');
      swatch.className = 'legend-swatch';
      swatch.style.background = color(s);

      const label = document.createElement('span');
      label.textContent = s;

      item.appendChild(swatch);
      item.appendChild(label);
      legendEl.appendChild(item);
    });
  }

  function renderTable(rows) {
    tbodyEl.innerHTML = '';
    state.rowByTicker.clear();

    rows.forEach((d) => {
      const tr = document.createElement('tr');
      tr.dataset.ticker = d.ticker;

      const tdTicker = document.createElement('td');
      tdTicker.textContent = d.ticker;

      const tdName = document.createElement('td');
      tdName.textContent = d.fullName || '—';

      const tdSector = document.createElement('td');
      tdSector.textContent = d.sector || '—';

      const tdMc = document.createElement('td');
      tdMc.className = 'num';
      tdMc.textContent = isETF(d) ? '—' : fmtMarketCap(d.marketCap);

      tr.appendChild(tdTicker);
      tr.appendChild(tdName);
      tr.appendChild(tdSector);
      tr.appendChild(tdMc);

      tr.addEventListener('click', () => setSelectedTicker(d.ticker));

      tbodyEl.appendChild(tr);
      state.rowByTicker.set(d.ticker, tr);
    });
  }

  function renderBubbleChart(nodes, sectors, color) {
    const width = chartEl.clientWidth - 20;
    const height = chartEl.clientHeight - 20;

    const svg = d3.select(chartEl)
      .append('svg')
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('width', '100%')
      .attr('height', '100%');

    const centers = computeSectorCenters(sectors, width, height);

    const nonEtf = nodes.filter(d => !isETF(d) && d.marketCap != null);
    const mcExtent = d3.extent(nonEtf, d => d.marketCap);
    const rScale = d3.scaleSqrt()
      .domain(mcExtent)
      .range([11, 48]);

    nodes.forEach(d => {
      d.r = isETF(d) ? 18 : rScale(d.marketCap);
    });

    deterministicInit(nodes, centers);

    const simulation = d3.forceSimulation(nodes)
      .alpha(1)
      .alphaDecay(0.045)
