.tooltip.visible {
  opacity: 1;
}

svg {
  display: block;
}

.node {
  cursor: pointer;
}

.node circle {
  stroke: rgba(255, 255, 255, 0.25);
  stroke-width: 1;
}

.node.selected circle {
  stroke: rgba(253, 224, 71, 0.95);
  stroke-width: 3;
}

.node text {
  fill: rgba(255,255,255,0.92);
  font-weight: 700;
  font-size: 11px;
  text-anchor: middle;
  dominant-baseline: middle;
  pointer-events: none;
}

@media (max-width: 1100px) {
  .layout {
    flex-direction: column;
  }
  .panel-chart,
  .panel-table {
    min-width: 0;
  }
  .chart {
    height: 560px;
  }
  .table-wrap {
    height: 520px;
  }
}
