  const tbodyEl = tableEl.querySelector('tbody');
  const tooltipEl = document.getElementById('tooltip');

  const state = {
    selectedTicker: null,
    byTicker: new Map(),
    rowByTicker: new Map(),
    nodeByTicker: new Map()
  };

