.panel h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 650;
  letter-spacing: 0.2px;
}

.hint {
  color: var(--muted);
  font-size: 12px;
}

.panel-chart {
  flex: 1 1 55%;
  min-width: 520px;
}

.panel-table {
  flex: 1 1 45%;
  min-width: 460px;
}

.chart {
  padding: 10px;
  height: 620px;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 10px;
  justify-content: flex-end;
  max-width: 520px;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(231, 237, 248, 0.10);
  font-size: 12px;
  color: var(--text);
  white-space: nowrap;
}

.legend-swatch {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  box-shadow: 0 0 0 2px rgba(0,0,0,0.20) inset;
}

.table-wrap {
  padding: 0;
  height: 660px;
  overflow: auto;
}

.stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

.stock-table thead th {
  position: sticky;
  top: 0;
  background: var(--panel2);
  z-index: 2;
}

.stock-table th,
.stock-table td {
  padding: 10px 10px;
  border-bottom: 1px solid rgba(231, 237, 248, 0.10);
  vertical-align: top;
}

.stock-table th {
  text-align: left;
  font-weight: 650;
  color: #dbe7ff;
}

.stock-table td {
  color: var(--text);
}

.stock-table td.num,
.stock-table th.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.stock-table tbody tr {
  cursor: pointer;
}

.stock-table tbody tr:hover {
  background: rgba(125, 211, 252, 0.08);
}

.stock-table tbody tr.selected {
  background: rgba(253, 224, 71, 0.14);
  outline: 2px solid rgba(253, 224, 71, 0.45);
  outline-offset: -2px;
}

.tooltip {
  position: absolute;
  left: 0;
  top: 0;
  padding: 10px 10px;
  background: rgba(0, 0, 0, 0.85);
  color: #fff;
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 10px;
  pointer-events: none;
  opacity: 0;
  transform: translate(0, 0);
  transition: opacity 120ms ease;
  z-index: 1000;
  font-size: 12px;
  line-height: 1.35;
  max-width: 320px;
}

.tooltip.visible {
  opacity: 1;
}

svg {
  display: block;
}

.node {
  cursor: pointer;
}

.node circle {
  stroke: rgba(255, 255, 255, 0.25);
  stroke-width: 1;
}

.node.selected circle {
  stroke: rgba(253, 224, 71, 0.95);
  stroke-width: 3;
}

.node text {
  fill: rgba(255,255,255,0.92);
  font-weight: 700;
  font-size: 11px;
  text-anchor: middle;
  dominant-baseline: middle;
  pointer-events: none;
}

@media (max-width: 1100px) {
  .layout {
    flex-direction: column;
  }
  .panel-chart,
  .panel-table {
    min-width: 0;
  }
  .chart {
    height: 560px;
  }
  .table-wrap {
    height: 520px;
  }
}
