}

.stock-table tbody tr:hover {
  background: rgba(125, 211, 252, 0.08);
}

.stock-table tbody tr.selected {
  background: rgba(253, 224, 71, 0.14);
  outline: 2px solid rgba(253, 224, 71, 0.45);
  outline-offset: -2px;
}

.tooltip {
  position: absolute;
  left: 0;
  top: 0;
  padding: 10px 10px;
  background: rgba(0, 0, 0, 0.85);
  color: #fff;
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 10px;
  pointer-events: none;
  opacity: 0;
  transform: translate(0, 0);
  transition: opacity 120ms ease;
  z-index: 1000;
  font-size: 12px;
  line-height: 1.35;
  max-width: 320px;
}

.tooltip.visible {
  opacity: 1;
}

svg {
  display: block;
}

.node {
  cursor: pointer;
}

.node circle {
  stroke: rgba(255, 255, 255, 0.25);
  stroke-width: 1;
}

.node.selected circle {
  stroke: rgba(253, 224, 71, 0.95);
  stroke-width: 3;
}

.node text {
  fill: rgba(255,255,255,0.92);
  font-weight: 700;
  font-size: 11px;
  text-anchor: middle;
  dominant-baseline: middle;
  pointer-events: none;
}

@media (max-width: 1100px) {
  .layout {
    flex-direction: column;
  }
  .panel-chart,
  .panel-table {
    min-width: 0;
  }
  .chart {
    height: 560px;
  }
  .table-wrap {
    height: 520px;
  }
}
